"use client";

/**
 * A text caret that blinks on the composition's clock, so every render of a
 * frame shows the same caret. Written by Better Design.
 */
import { useCurrentFrame, useVideoConfig } from "remotion";

/** Props for the caret. */
export interface CaretProps {
  color: string;
  /** Height in pixels. Match the line's font size. */
  height: number;
  /** Hold it solid, as a caret does while text is arriving. */
  solid?: boolean;
  /** Blinks a second. */
  rate?: number;
}

/** A vertical bar that blinks while idle and holds solid while typing. */
export function Caret({ color, height, solid = false, rate = 1.1 }: CaretProps) {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  const phase = ((frame / fps) * rate) % 1;
  const on = solid || phase < 0.55;
  return (
    <span
      aria-hidden="true"
      style={{
        display: "inline-block",
        width: Math.max(2, Math.round(height * 0.07)),
        height,
        marginLeft: Math.round(height * 0.06),
        borderRadius: 2,
        background: color,
        opacity: on ? 1 : 0,
        verticalAlign: "text-bottom",
      }}
    />
  );
}

/**
 * Colour helpers for themes given as concrete colours. They read any CSS
 * colour culori understands, oklch included, and mix in OKLab so a blend of
 * two tokens stays in the product's palette.
 *
 * Written by Better Design.
 */
import { clampChroma, formatCss, interpolate, oklch, parse, rgb } from "culori";

const FALLBACK = { mode: "oklch", l: 0.6, c: 0, h: 0 } as const;

/** Read a colour, or fall back to mid grey so a bad token never crashes a render. */
function read(color: string) {
  return parse(color) ?? FALLBACK;
}

/** The colour with its alpha set, as `oklch()` CSS. */
export function withAlpha(color: string, alpha: number): string {
  const value = oklch(read(color)) ?? FALLBACK;
  return formatCss({ ...value, h: value.h ?? 0, alpha }) ?? color;
}

/**
 * A blend `t` of the way from `a` to `b`. It mixes in OKLab, not along the
 * OKLCH hue wheel, so blue toward white stays blue and never passes through
 * pink when one end is a grey.
 */
export function mix(a: string, b: string, t: number): string {
  const value = clampChroma(interpolate([read(a), read(b)], "oklab")(t), "oklch");
  return formatCss(oklch(value)) ?? a;
}

/** The colour turned `degrees` around the OKLCH hue wheel, same lightness and chroma. */
export function shiftHue(color: string, degrees: number): string {
  const value = oklch(read(color));
  const hue = ((value?.h ?? 0) + degrees + 360) % 360;
  return formatCss({ mode: "oklch", l: value?.l ?? 0.6, c: value?.c ?? 0, h: hue }) ?? color;
}

/** Red, green and blue from 0 to 1, for code that draws pixels itself. */
export function channels(color: string): { r: number; g: number; b: number } {
  const value = rgb(read(color));
  return { r: value?.r ?? 0, g: value?.g ?? 0, b: value?.b ?? 0 };
}

/**
 * Device frames for the video components: a recent Pro iPhone and a 14-inch
 * laptop lid, drawn from published hardware measurements so a demo reads as a
 * real device. The screen is its own layer, clipped to the display outline;
 * the case, glass, buttons and camera are drawn around and above it.
 *
 * Written by Better Design. The outlines are approximations of the published
 * dimensional drawings, not traced artwork, and they carry no logo.
 */
import type { CSSProperties, ReactNode } from "react";

type Point = readonly [number, number];

/** One corner's outline from the top edge round to the side, in millimetres from the corner. */
const PHONE_CORNER: readonly Point[] = [
  [19.43, 0], [13.9, 0.04], [8.46, 0.92], [3.8, 3.8], [0.92, 8.46], [0.04, 13.9], [0, 19.43],
];

/** Pro iPhone hardware, in millimetres, from the front dimensional drawing. */
const PHONE_MM = {
  case: { w: 71.85, h: 150.01 },
  display: { w: 66.57, h: 144.73 },
  /** The metal band seen from the front, before the glass starts. */
  rim: 0.9,
  island: { cx: 35.925, cy: 7.99, w: 15.66, h: 6.07 },
  /** Centre from the top and length, per side. */
  left: [[34.28, 6.9], [48.43, 11.2], [62.63, 11.2]] as const,
  right: [[55.53, 17.7]] as const,
  protrusion: 0.45,
};

/** The phone screen in points: what the content inside a PhoneFrame is laid out at. */
export const PHONE_SCREEN = { width: 402, height: 874 } as const;

const MM = PHONE_SCREEN.width / PHONE_MM.display.w;
const CASE_W = PHONE_MM.case.w * MM;
const CASE_H = PHONE_MM.case.h * MM;
const INSET = ((PHONE_MM.case.w - PHONE_MM.display.w) / 2) * MM;

/** The phone case in points, buttons excluded. */
export const PHONE_CASE = { width: CASE_W, height: CASE_H } as const;

/** Hardware inks. They stay the same in light and dark films, like real hardware. */
const INK = {
  metalHigh: "oklch(0.52 0.006 260)",
  metal: "oklch(0.36 0.005 260)",
  metalLow: "oklch(0.24 0.005 260)",
  glass: "oklch(0.13 0.003 260)",
  island: "oklch(0.06 0 0)",
};

/**
 * A closed outline: straight edges joined by smooth corners that pass through
 * the profile points, so the curvature stays continuous like the real case.
 */
function outline(w: number, h: number, profile: readonly Point[]): string {
  const tl = [...profile].reverse().map(([x, y]): Point => [x, y]);
  const tr = profile.map(([x, y]): Point => [w - x, y]);
  const br = profile.map(([x, y]): Point => [w - y, h - x]);
  const bl = [...profile].reverse().map(([x, y]): Point => [y, h - x]);
  const corners: { pts: Point[]; into: Point; out: Point }[] = [
    { pts: tl, into: [0, -1], out: [1, 0] },
    { pts: tr, into: [1, 0], out: [0, 1] },
    { pts: br, into: [0, 1], out: [-1, 0] },
    { pts: bl, into: [-1, 0], out: [0, -1] },
  ];
  const f = (n: number) => n.toFixed(2);
  let d = `M ${f(tl[0][0])} ${f(tl[0][1])}`;
  for (const { pts, into, out } of corners) {
    d += ` L ${f(pts[0][0])} ${f(pts[0][1])}`;
    const gap = Math.hypot(pts[1][0] - pts[0][0], pts[1][1] - pts[0][1]);
    const tail = Math.hypot(pts.at(-1)![0] - pts.at(-2)![0], pts.at(-1)![1] - pts.at(-2)![1]);
    const ext: Point[] = [
      [pts[0][0] - into[0] * gap, pts[0][1] - into[1] * gap],
      ...pts,
      [pts.at(-1)![0] + out[0] * tail, pts.at(-1)![1] + out[1] * tail],
    ];
    for (let i = 1; i < ext.length - 2; i++) {
      const [p0, p1, p2, p3] = [ext[i - 1], ext[i], ext[i + 1], ext[i + 2]];
      const c1: Point = [p1[0] + (p2[0] - p0[0]) / 6, p1[1] + (p2[1] - p0[1]) / 6];
      const c2: Point = [p2[0] - (p3[0] - p1[0]) / 6, p2[1] - (p3[1] - p1[1]) / 6];
      d += ` C ${f(c1[0])} ${f(c1[1])} ${f(c2[0])} ${f(c2[1])} ${f(p2[0])} ${f(p2[1])}`;
    }
  }
  return `${d} Z`;
}

/** The corner profile in points, shrunk for an outline inset `inset` millimetres inside the case. */
function profileAt(inset: number): Point[] {
  const scale = (PHONE_CORNER[0][0] - inset) / PHONE_CORNER[0][0];
  return PHONE_CORNER.map(([x, y]): Point => [x * scale * MM, y * scale * MM]);
}

const CASE_PATH = outline(CASE_W, CASE_H, profileAt(0));
const GLASS_INSET = PHONE_MM.rim * MM;
const GLASS_PATH = outline(CASE_W - 2 * GLASS_INSET, CASE_H - 2 * GLASS_INSET, profileAt(PHONE_MM.rim));
const SCREEN_PATH = outline(PHONE_SCREEN.width, PHONE_SCREEN.height, profileAt((PHONE_MM.case.w - PHONE_MM.display.w) / 2));

/** Props for PhoneFrame. */
export interface PhoneFrameProps {
  /** Rendered width of the case in pixels. The whole device scales from it, so nothing stretches. */
  width?: number;
  /** The screen, laid out at PHONE_SCREEN points. Media inside should use object-fit cover or contain. */
  children?: ReactNode;
  /** Draw the Dynamic Island over the screen. Leave it on unless the content already shows one. */
  island?: boolean;
  /** Extra layers above the screen and below the island, such as a glare sweep. */
  overlay?: ReactNode;
  style?: CSSProperties;
}

/** A Pro iPhone seen from the front: metal band, glass, side buttons and Dynamic Island around your screen. */
export function PhoneFrame({ width = 420, children, island = true, overlay, style }: PhoneFrameProps) {
  const scale = width / CASE_W;
  const button = (side: "left" | "right", top: number, length: number, i: number) => (
    <div
      key={`${side}${i}`}
      style={{
        position: "absolute",
        [side]: -PHONE_MM.protrusion * MM,
        top: (top - length / 2) * MM,
        width: PHONE_MM.protrusion * MM + 2,
        height: length * MM,
        borderRadius: "0.125rem",
        background: `linear-gradient(${side === "left" ? 90 : 270}deg, ${INK.metalLow}, ${INK.metal})`,
      }}
    />
  );
  const { island: isl } = PHONE_MM;
  return (
    <div style={{ position: "relative", width, height: CASE_H * scale, ...style }}>
      <div style={{ position: "absolute", left: 0, top: 0, width: CASE_W, height: CASE_H, transform: `scale(${scale})`, transformOrigin: "0 0" }}>
        {PHONE_MM.left.map(([top, length], i) => button("left", top, length, i))}
        {PHONE_MM.right.map(([top, length], i) => button("right", top, length, i))}
        <svg width={CASE_W} height={CASE_H} viewBox={`0 0 ${CASE_W} ${CASE_H}`} style={{ position: "absolute", inset: 0, overflow: "visible" }}>
          <defs>
            <linearGradient id="bd-phone-metal" x1="0" y1="0" x2="1" y2="1">
              <stop offset="0" stopColor={INK.metalHigh} />
              <stop offset="0.45" stopColor={INK.metal} />
              <stop offset="1" stopColor={INK.metalLow} />
            </linearGradient>
          </defs>
          <path d={CASE_PATH} fill="url(#bd-phone-metal)" />
          <path d={GLASS_PATH} transform={`translate(${GLASS_INSET} ${GLASS_INSET})`} fill={INK.glass} />
        </svg>
        <div
          style={{
            position: "absolute",
            left: INSET,
            top: INSET,
            width: PHONE_SCREEN.width,
            height: PHONE_SCREEN.height,
            clipPath: `path("${SCREEN_PATH}")`,
            overflow: "hidden",
          }}
        >
          {children}
          {overlay}
          {island ? (
            <div
              style={{
                position: "absolute",
                left: isl.cx * MM - INSET - (isl.w * MM) / 2,
                top: isl.cy * MM - INSET - (isl.h * MM) / 2,
                width: isl.w * MM,
                height: isl.h * MM,
                borderRadius: (isl.h * MM) / 2,
                background: INK.island,
              }}
            />
          ) : null}
        </div>
      </div>
    </div>
  );
}

/** A 14-inch laptop, in points: the screen, the black bezel and the metal edge of the lid, then the base. */
export const LAPTOP = {
  screen: { width: 1512, height: 982 },
  bezel: { side: 16, top: 16, bottom: 22 },
  edge: 4,
  lidCorner: 24,
  notch: { width: 196, height: 32 },
  base: { overhang: 50, height: 38 },
} as const;

/** The lid in points: the screen plus the bezel and metal edge round it. */
export const LAPTOP_LID = {
  width: LAPTOP.screen.width + 2 * (LAPTOP.bezel.side + LAPTOP.edge),
  height: LAPTOP.screen.height + LAPTOP.bezel.top + LAPTOP.bezel.bottom + 2 * LAPTOP.edge,
} as const;

/** Props for LaptopLid. */
export interface LaptopLidProps {
  /** The screen, laid out at LAPTOP.screen points. */
  children?: ReactNode;
  /** Layers above the screen and below the notch. */
  overlay?: ReactNode;
  style?: CSSProperties;
}

/**
 * The open lid of a 14-inch laptop, front view, at native points: metal edge,
 * black bezel, a screen with rounded top corners and the camera notch. Scale
 * it with a transform; it does not size itself.
 */
export function LaptopLid({ children, overlay, style }: LaptopLidProps) {
  const { screen, bezel, edge, lidCorner, notch } = LAPTOP;
  return (
    <div
      style={{
        position: "relative",
        width: LAPTOP_LID.width,
        height: LAPTOP_LID.height,
        borderRadius: `${lidCorner}px ${lidCorner}px 10px 10px`,
        padding: edge,
        background: `linear-gradient(180deg, ${INK.metalHigh}, ${INK.metal} 30%, ${INK.metalLow})`,
        ...style,
      }}
    >
      <div
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          borderRadius: `${(lidCorner - edge) / 16}rem ${(lidCorner - edge) / 16}rem 0.4375rem 0.4375rem`,
          background: INK.glass,
          padding: `${bezel.top}px ${bezel.side}px ${bezel.bottom}px`,
        }}
      >
        <div style={{ position: "relative", width: screen.width, height: screen.height, borderRadius: "0.625rem 0.625rem 0 0", overflow: "hidden" }}>
          {children}
          {overlay}
          <div
            style={{
              position: "absolute",
              top: 0,
              left: (screen.width - notch.width) / 2,
              width: notch.width,
              height: notch.height,
              borderRadius: "0 0 12px 12px",
              background: INK.glass,
            }}
          />
        </div>
      </div>
    </div>
  );
}

/**
 * The Better Design video kit: the theme every component paints from, shared
 * motion, colour helpers, a caret and a text field.
 *
 * Written by Better Design.
 */
export { Caret, type CaretProps } from "./caret";
export { channels, mix, shiftHue, withAlpha } from "./color";
export { type EasingName, easings, progress, springs, typed, unit } from "./motion";
export { srcOf } from "./media";
export { LAPTOP, LAPTOP_LID, LaptopLid, type LaptopLidProps, PHONE_CASE, PHONE_SCREEN, PhoneFrame, type PhoneFrameProps } from "./device-frame";
export { TextField, type TextFieldProps } from "./text-field";
export {
  darkVideoTheme,
  lightVideoTheme,
  pickFont,
  useVideoTheme,
  type VideoTheme,
  VideoThemeProvider,
} from "./theme";
export {
  cueGain,
  cuesOn,
  cueStart,
  cueStartFrame,
  dbToGain,
  type MixOptions,
  mixTrim,
  musicLevel,
  SFX_BASE_URL,
  SFX_GAIN_DB,
  SFX_LAYER,
  type SfxName,
  sfxSrc,
  shiftCues,
  type SoundCue,
  type SoundLayer,
  SOUND_LAYER_LABELS,
  SOUND_LAYERS,
  typingCues,
} from "./sound";
export { SFX_DATA } from "./sfx-data";
export { SoundTrack, type SoundTrackProps } from "./sound-track";

/**
 * Where a picture or a recording loads from. Written by Better Design.
 */
import { staticFile } from "remotion";

/** A URL, a data URI or an absolute path stays as it is; any other path is read from the project's public/ folder. */
export const srcOf = (entry: string): string => (/^(https?:|data:|\/)/.test(entry) ? entry : staticFile(entry));

/**
 * Easing curves and spring settings shared by the Better Design video
 * components, so every scene moves with the same weight.
 *
 * Written by Better Design.
 */

/** Curves that take progress from 0 to 1 and return eased progress. */
export const easings = {
  linear: (t: number): number => t,
  /** Fast start, long settle: the default for anything arriving. */
  out: (t: number): number => 1 - (1 - t) ** 4,
  /** Slow start: for anything leaving. */
  in: (t: number): number => t ** 3,
  inOut: (t: number): number => (t < 0.5 ? 8 * t ** 4 : 1 - (-2 * t + 2) ** 4 / 2),
  /** Arrives, passes its mark by a little and comes back. */
  overshoot: (t: number): number => {
    const k = 1.7;
    return 1 + (k + 1) * (t - 1) ** 3 + k * (t - 1) ** 2;
  },
} as const;

/** One easing curve by name. */
export type EasingName = keyof typeof easings;

/** Spring configs for Remotion's `spring()`. */
export const springs = {
  /** Lands quickly with no bounce: controls, chips, cards. */
  snappy: { damping: 20, stiffness: 240, mass: 0.7 },
  /** A slower, heavier arrival: devices and large surfaces. */
  soft: { damping: 16, stiffness: 110, mass: 1 },
  /** A visible bounce: counters, badges, a pressed button. */
  bouncy: { damping: 11, stiffness: 190, mass: 0.8 },
} as const;

/** Clamp a number into 0 to 1. */
export const unit = (value: number): number => Math.min(1, Math.max(0, value));

/** Progress of `frame` through the window that starts at `start` and lasts `length` frames. */
export const progress = (frame: number, start: number, length: number): number =>
  length <= 0 ? (frame >= start ? 1 : 0) : unit((frame - start) / length);

/** How many characters of `text` show at `frame`, typing `perSecond` characters a second. */
export function typed(text: string, frame: number, start: number, fps: number, perSecond = 28): string {
  const count = Math.floor(((frame - start) / fps) * perSecond);
  return text.slice(0, Math.max(0, Math.min(text.length, count)));
}

/**
 * Plays a list of sound cues, and the music bed under them, at the levels the
 * mixer in sound.ts sets. Put one SoundTrack at the top of a film with every
 * scene's cues shifted onto the film's clock.
 *
 * Written by Better Design. The sound files are CC0. [BD-1155]
 */
import { useMemo } from "react";
import { Audio } from "@remotion/media";
import { useVideoConfig } from "remotion";
import {
  cueGain,
  cueStartFrame,
  cuesOn,
  type MixOptions,
  mixTrim,
  musicLevel,
  SFX_BASE_URL,
  type SoundCue,
  type SoundLayer,
  SOUND_LAYERS,
  sfxSrc,
} from "./sound";
import { SFX_DATA } from "./sfx-data";

export interface SoundTrackProps {
  cues: readonly SoundCue[];
  /** Play the music bed under the effects. A film ships with and without it from the same cues. */
  music?: boolean;
  /** Only these layers sound. Every layer by default; a breakdown solos them one by one. */
  layers?: readonly SoundLayer[];
  /** Where the sound files are served. Defaults to better-design.com; pass staticFile("sfx") once copied into public/. */
  base?: string;
  mix?: MixOptions;
  /** The frames the mix trim covers. Defaults to the composition's length; a breakdown passes one pass of the film. */
  durationInFrames?: number;
}

/** Every cue at its level, the music ducked under the whooshes and hits, and the whole mix trimmed under -1 dBFS. */
export function SoundTrack({ cues, music = true, layers = SOUND_LAYERS, base = SFX_BASE_URL, mix, durationInFrames }: SoundTrackProps) {
  const config = useVideoConfig();
  const fps = config.fps;
  const frames = durationInFrames ?? config.durationInFrames;
  const heard = useMemo(() => cuesOn(cues, layers), [cues, layers]);
  const withMusic = music && layers.includes("music");
  // The trim covers the full mix, heard or not, so soloing a layer never changes its level.
  const trim = useMemo(() => mixTrim(cues, fps, frames, music, mix), [cues, fps, frames, music, mix]);
  return (
    <>
      {withMusic ? (
        <Audio
          src={sfxSrc("music-bed", base)}
          loop
          loopVolumeCurveBehavior="extend"
          volume={(frame) => musicLevel(frame, cues, fps, mix) * trim}
        />
      ) : null}
      {heard.map((cue, i) => {
        const start = cueStartFrame(cue, fps);
        const length = Math.ceil(SFX_DATA[cue.sfx].duration * fps) + 1;
        return (
          <Audio
            key={i}
            src={sfxSrc(cue.sfx, base)}
            from={Math.max(0, start)}
            trimBefore={Math.max(0, -start)}
            durationInFrames={length}
            volume={cueGain(cue) * trim}
          />
        );
      })}
    </>
  );
}

/**
 * Sound for Better Design video components: the cue a component emits, the
 * layer each effect belongs to, and the mixer that sets every level. It holds
 * no Remotion code, so the player in sound-track.tsx and an offline renderer
 * mix the same cues to the same levels.
 *
 * A cue names the frame where the action happens on screen. The mixer starts
 * the file early by the time it takes to reach its loudest point, so a whoosh
 * peaks on the cut and a riser peaks on the reveal.
 *
 * Written by Better Design. The sound files are CC0. [BD-1155]
 */
import { SFX_DATA } from "./sfx-data";

/** A file in the Better Design sound pack. */
export type SfxName = keyof typeof SFX_DATA;

/** The groups a breakdown shows, one lane each, in the order a mix is built up. */
export type SoundLayer = "keys" | "clicks" | "pops" | "whooshes" | "hits" | "music";

/** Every layer, in build-up order. */
export const SOUND_LAYERS: readonly SoundLayer[] = ["keys", "clicks", "pops", "whooshes", "hits", "music"];

/** The label a breakdown prints beside each layer. */
export const SOUND_LAYER_LABELS: Record<SoundLayer, string> = {
  keys: "Keys",
  clicks: "Clicks",
  pops: "Pops",
  whooshes: "Whooshes",
  hits: "Risers and hits",
  music: "Music",
};

/** Which layer each file sits on. */
export const SFX_LAYER: Record<SfxName, SoundLayer> = {
  click: "clicks",
  "key-a": "keys",
  "key-b": "keys",
  pop: "pops",
  "pop-soft": "pops",
  whoosh: "whooshes",
  "whoosh-long": "whooshes",
  swish: "whooshes",
  riser: "hits",
  shimmer: "hits",
  "logo-hit": "hits",
  "music-bed": "music",
};

/**
 * Each file's starting level in dB. Every file is finished to -1 dBFS, so
 * these set the balance: keys sit low, the logo hit sits near the top.
 */
export const SFX_GAIN_DB: Record<SfxName, number> = {
  click: -7,
  "key-a": -19,
  "key-b": -19,
  pop: -12,
  "pop-soft": -15,
  whoosh: -11,
  "whoosh-long": -12,
  swish: -14,
  riser: -12,
  shimmer: -16,
  "logo-hit": -5,
  "music-bed": -14,
};

/** One sound: the effect, the frame of the action it marks, and a level change in dB from the file's default. */
export interface SoundCue {
  sfx: Exclude<SfxName, "music-bed">;
  /** The frame where the action lands on screen, on the clock of the component that emits it. */
  at: number;
  /** dB added to the file's default level. Negative is quieter. */
  gain?: number;
}

/** Where the files are served. A project can copy them into public/ and pass its own base. */
export const SFX_BASE_URL = "https://better-design.com/video/sfx/v1";

/** The address of one file. */
export const sfxSrc = (name: SfxName, base: string = SFX_BASE_URL): string => `${base}/${name}.wav`;

/** dB to a linear gain. */
export const dbToGain = (db: number): number => Math.pow(10, db / 20);

/** The frame a cue's file starts on, before rounding: the action frame minus the time to the file's loudest point. */
export const cueStart = (cue: SoundCue, fps: number): number => cue.at - SFX_DATA[cue.sfx].hitAt * fps;

/** The whole frame a cue's file starts on, as the player plays it. The mixer bounds the same frame. */
export const cueStartFrame = (cue: SoundCue, fps: number): number => Math.round(cueStart(cue, fps));

/** The cue's level, linear, before the mix trim. */
export const cueGain = (cue: SoundCue): number => dbToGain(SFX_GAIN_DB[cue.sfx] + (cue.gain ?? 0));

/** Move cues onto a parent clock, for a component placed `by` frames into a film. */
export const shiftCues = (cues: readonly SoundCue[], by: number): SoundCue[] => cues.map((cue) => ({ ...cue, at: cue.at + by }));

/** Keep the cues on the given layers. */
export const cuesOn = (cues: readonly SoundCue[], layers: readonly SoundLayer[]): SoundCue[] =>
  cues.filter((cue) => layers.includes(SFX_LAYER[cue.sfx]));

/**
 * A run of keystrokes that never sounds like a machine gun: the two key takes
 * alternate, spaces land softer, and the level drifts down a little along the
 * line, as docs/motion/beat-sync-and-sound.md asks.
 */
export function typingCues(text: string, firstFrame: number, charsPerSecond: number, fps: number): SoundCue[] {
  // UTF-16 units, the way typed() in motion.ts counts them, so each key lands with its glyph.
  const chars = text.split("");
  return chars.map((char, i) => ({
    sfx: i % 2 === 0 ? "key-a" : "key-b",
    at: firstFrame + (i * fps) / charsPerSecond,
    gain: (char === " " ? -4 : 0) - (3 * i) / Math.max(1, chars.length - 1) + (i % 3 === 0 ? 1 : 0),
  }));
}

/** How the music sits under the effects. */
export interface MixOptions {
  /** dB added to the music bed's default level. */
  musicGain?: number;
  /** How far the music dips under a whoosh or a hit, in dB. */
  duckDb?: number;
  /** Frames the music takes to dip before the effect. */
  duckAttack?: number;
  /** Frames the music takes to come back after it. */
  duckRelease?: number;
  /** The loudest the summed mix may reach, in dBFS. */
  ceilingDb?: number;
}

const DEFAULT_MIX: Required<MixOptions> = { musicGain: 0, duckDb: -7, duckAttack: 4, duckRelease: 16, ceilingDb: -1 };

const DUCKING_LAYERS: readonly SoundLayer[] = ["whooshes", "hits"];

/**
 * The music's level at `frame`, linear: its default level, dipped under each
 * whoosh and hit. The dip starts `duckAttack` frames before the file does and
 * holds until the file's loudest point has passed, then comes back.
 */
export function musicLevel(frame: number, cues: readonly SoundCue[], fps: number, options: MixOptions = {}): number {
  const mix = { ...DEFAULT_MIX, ...options };
  let dip = 0;
  for (const cue of cues) {
    if (!DUCKING_LAYERS.includes(SFX_LAYER[cue.sfx])) continue;
    const start = cueStart(cue, fps);
    const hold = cue.at + 0.25 * SFX_DATA[cue.sfx].duration * fps;
    let amount = 0;
    if (frame >= start - mix.duckAttack && frame < start) amount = (frame - (start - mix.duckAttack)) / mix.duckAttack;
    else if (frame >= start && frame <= hold) amount = 1;
    else if (frame > hold && frame < hold + mix.duckRelease) amount = 1 - (frame - hold) / mix.duckRelease;
    dip = Math.max(dip, amount);
  }
  return dbToGain(SFX_GAIN_DB["music-bed"] + mix.musicGain + mix.duckDb * dip);
}

/** The loudest sample of a file between two times, in seconds from its start, read from its waveform. */
function peakBetween(name: SfxName, from: number, to: number): number {
  const { wave, duration } = SFX_DATA[name];
  const first = Math.max(0, Math.floor((from / duration) * wave.length));
  const last = Math.min(wave.length - 1, Math.floor((to / duration) * wave.length));
  let peak = 0;
  for (let i = first; i <= last; i++) peak = Math.max(peak, wave[i]);
  return peak;
}

/**
 * One gain for the whole mix that keeps it under the ceiling. For every frame
 * it adds the loudest sample each sounding file can reach in that frame, at
 * its level, plus the music's. That sum is the most the mix can reach there,
 * so a trim under it can never clip. It returns 1 when the mix already fits.
 */
export function mixTrim(cues: readonly SoundCue[], fps: number, durationInFrames: number, music: boolean, options: MixOptions = {}): number {
  const mix = { ...DEFAULT_MIX, ...options };
  const musicPeak = Math.max(...SFX_DATA["music-bed"].wave);
  let loudest = 0;
  for (let frame = 0; frame < durationInFrames; frame++) {
    // The renderer ramps the music toward the next frame's level, so bound it by the louder of the two.
    let sum = music ? musicPeak * Math.max(musicLevel(frame, cues, fps, options), musicLevel(frame + 1, cues, fps, options)) : 0;
    for (const cue of cues) {
      const start = (frame - cueStartFrame(cue, fps)) / fps;
      const end = start + 1 / fps;
      if (end <= 0 || start >= SFX_DATA[cue.sfx].duration) continue;
      sum += peakBetween(cue.sfx, Math.max(0, start), end) * cueGain(cue);
    }
    loudest = Math.max(loudest, sum);
  }
  const ceiling = dbToGain(mix.ceilingDb);
  return loudest > ceiling ? ceiling / loudest : 1;
}

