/**
 * A text field drawn for video: its border, ring and caret follow the state
 * the scene passes for each frame. Written by Better Design.
 */
import type { ReactNode } from "react";

import { Caret } from "./caret";
import { withAlpha } from "./color";
import type { VideoTheme } from "./theme";

/** Props for the text field. */
export interface TextFieldProps {
  theme: VideoTheme;
  /** The text showing in the field this frame. */
  value: string;
  placeholder?: string;
  /** Focused fields draw the ring; typing ones hold the caret solid. */
  state: "idle" | "focused" | "typing";
  fontSize?: number;
  fontFamily?: string;
  width?: number | string;
  /** Content after the text, such as a send button. */
  trailing?: ReactNode;
  /** Content before the text, such as a search icon. */
  leading?: ReactNode;
}

/** One line of input with a placeholder, a caret and a focus ring. */
export function TextField({ theme, value, placeholder = "", state, fontSize = 36, fontFamily, width = "100%", leading, trailing }: TextFieldProps) {
  const focused = state !== "idle";
  return (
    <div
      style={{
        width,
        display: "flex",
        alignItems: "center",
        gap: fontSize * 0.5,
        padding: `${fontSize * 0.55}px ${fontSize * 0.7}px`,
        borderRadius: theme.radius * 1.6,
        background: theme.card,
        border: `2px solid ${focused ? theme.ring : theme.border}`,
        boxShadow: focused
          ? `0 0 0 ${fontSize * 0.18}px ${withAlpha(theme.ring, 0.16)}, 0 ${fontSize * 0.5}px ${fontSize * 1.4}px ${withAlpha(theme.foreground, 0.08)}`
          : `0 ${fontSize * 0.3}px ${fontSize}px ${withAlpha(theme.foreground, 0.06)}`,
        fontFamily,
        fontSize,
        color: theme.cardForeground,
      }}
    >
      {leading}
      <span style={{ flex: 1, whiteSpace: "nowrap", overflow: "hidden" }}>
        {value ? value : <span style={{ color: theme.mutedForeground }}>{placeholder}</span>}
        {focused ? <Caret color={theme.ring} height={fontSize * 1.05} solid={state === "typing"} /> : null}
      </span>
      {trailing}
    </div>
  );
}

