interface VideoThemeContextValue {
  /** Pass `darkVideoTheme` for a dark film, or your own tokens on top of either. */
  theme?: Partial<VideoTheme>;
}

const VideoThemeContext = createContext<VideoThemeContextValue>({});

/** Set the theme once for every component inside a composition. */
export function VideoThemeProvider({ theme, children }: VideoThemeContextValue & { children: ReactNode }) {
  return createElement(VideoThemeContext.Provider, { value: { theme } }, children);
}

/** The resolved theme: the light defaults, then the provider, then the component's own override. */
export function useVideoTheme(override?: Partial<VideoTheme>): VideoTheme {
  const context = useContext(VideoThemeContext);
  return { ...lightVideoTheme, ...context.theme, ...override };
}

/** The face a scene paints with: the caller's font, then the theme's, then the scene's own. */
export function pickFont(font: string | undefined, theme: VideoTheme, fallback: string): string {
  return font || theme.fontFamily || fallback;
}
